var Ri={"The Optical Pulse \xB7 Apple Watch Heart Rate":"\u5149\u3067\u8AAD\u3080\u8108\u62CD \xB7 Apple Watch\u306E\u5FC3\u62CD\u6570\u6E2C\u5B9A","Explore how Apple Watch turns reflected light into a heart rate with an interactive 3D wrist cutaway and pulse laboratory.":"Apple Watch\u306F\u5149\u304B\u3089\u3069\u306E\u3088\u3046\u306B\u5FC3\u62CD\u6570\u3092\u6C42\u3081\u308B\u306E\u3067\u3057\u3087\u3046\u304B\u3002\u624B\u9996\u306E3D\u65AD\u9762\u3068\u8108\u6CE2\u306E\u5B9F\u9A13\u3067\u3001\u305D\u306E\u3057\u304F\u307F\u3092\u63A2\u308A\u307E\u3059\u3002","SENSOR STUDIES":"\u30BB\u30F3\u30B5\u30FC\u306E\u3057\u304F\u307F","APPLE WATCH \xB7 OPTICAL HEART RATE":"APPLE WATCH \xB7 \u5149\u5B66\u5F0F\u5FC3\u62CD\u6570\u6E2C\u5B9A","Sources & model":"\u51FA\u5178\u3068\u30E2\u30C7\u30EB","A heartbeat, seen in light.":"\u5149\u3067\u3001\u5FC3\u62CD\u3092\u8AAD\u307F\u53D6\u308B\u3002","Follow a pulse from your wrist to the number on your watch.":"\u624B\u9996\u306E\u8108\u62CD\u304C\u3001\u6642\u8A08\u306E\u6570\u5024\u306B\u306A\u308B\u307E\u3067\u3092\u8FFD\u3044\u307E\u3059\u3002","Explore the mechanism":"\u6E2C\u5B9A\u306E\u3057\u304F\u307F\u3092\u63A2\u308B","Send light":"\u5149\u3092\u9001\u308B","Reveal a pulse":"\u8108\u62CD\u3092\u6349\u3048\u308B","Measure the rhythm":"\u30EA\u30BA\u30E0\u3092\u6E2C\u308B","Disturb the signal":"\u4FE1\u53F7\u3092\u4E71\u3059","Interactive three-dimensional watch and wrist":"\u6642\u8A08\u3068\u624B\u9996\u306E\u30A4\u30F3\u30BF\u30E9\u30AF\u30C6\u30A3\u30D63D\u30E2\u30C7\u30EB","WRIST CUTAWAY":"\u624B\u9996\u306E\u65AD\u9762","Layers separated for inspection":"\u89B3\u5BDF\u306E\u305F\u3081\u3001\u5C64\u3092\u96E2\u3057\u3066\u8868\u793A","3D rendering is unavailable":"3D\u3092\u8868\u793A\u3067\u304D\u307E\u305B\u3093","Try a browser with WebGL enabled. The signal experiment and all explanations below still work.":"WebGL\u304C\u6709\u52B9\u306A\u30D6\u30E9\u30A6\u30B6\u3067\u304A\u8A66\u3057\u304F\u3060\u3055\u3044\u3002\u8108\u6CE2\u306E\u5B9F\u9A13\u3068\u4EE5\u4E0B\u306E\u89E3\u8AAC\u306F\u5F15\u304D\u7D9A\u304D\u5229\u7528\u3067\u304D\u307E\u3059\u3002","Camera views":"\u8996\u70B9\u306E\u9078\u629E",Cutaway:"\u65AD\u9762","Sensor back":"\u80CC\u9762\u30BB\u30F3\u30B5\u30FC",Watch:"\u6642\u8A08\u5168\u4F53","Reset view":"\u8996\u70B9\u3092\u623B\u3059","Drag to orbit \xB7 pinch or scroll to zoom":"\u30C9\u30E9\u30C3\u30B0\u3067\u56DE\u8EE2 \xB7 \u30D4\u30F3\u30C1\u3084\u30B9\u30AF\u30ED\u30FC\u30EB\u3067\u62E1\u5927",Pause:"\u4E00\u6642\u505C\u6B62",Play:"\u518D\u751F","01 / SEND LIGHT":"01 / \u5149\u3092\u9001\u308B","02 / REVEAL A PULSE":"02 / \u8108\u62CD\u3092\u6349\u3048\u308B","03 / MEASURE THE RHYTHM":"03 / \u30EA\u30BA\u30E0\u3092\u6E2C\u308B","04 / DISTURB THE SIGNAL":"04 / \u4FE1\u53F7\u3092\u4E71\u3059","Your watch illuminates your wrist.":"\u6642\u8A08\u304C\u624B\u9996\u306B\u5149\u3092\u5F53\u3066\u307E\u3059\u3002","Green LEDs shine into the skin. Some light is absorbed; some scatters back to photodiodes beside the LEDs.":"\u7DD1\u8272LED\u304C\u76AE\u819A\u306B\u5149\u3092\u9001\u308A\u307E\u3059\u3002\u4E00\u90E8\u306F\u5438\u53CE\u3055\u308C\u3001\u4E00\u90E8\u306F\u6563\u4E71\u3057\u3066LED\u306E\u8FD1\u304F\u306B\u3042\u308B\u30D5\u30A9\u30C8\u30C0\u30A4\u30AA\u30FC\u30C9\u306B\u623B\u308A\u307E\u3059\u3002","Emitter \u2192 tissue \u2192 detector":"\u767A\u5149\u90E8 \u2192 \u7D44\u7E54 \u2192 \u53D7\u5149\u90E8","Simulated heart rate":"\u30E2\u30C7\u30EB\u306E\u5FC3\u62CD\u6570","Light source":"\u5149\u306E\u7A2E\u985E","Green \xB7 workout example":"\u7DD1\u8272\u5149 \xB7 \u30EF\u30FC\u30AF\u30A2\u30A6\u30C8\u306E\u4F8B","Infrared \xB7 background example":"\u8D64\u5916\u5149 \xB7 \u30D0\u30C3\u30AF\u30B0\u30E9\u30A6\u30F3\u30C9\u6E2C\u5B9A\u306E\u4F8B","LED flashes are hundreds of times per second. The paths here are slowed and enlarged.":"\u5B9F\u969B\u306ELED\u306F\u6BCE\u79D2\u6570\u767E\u56DE\u70B9\u6EC5\u3057\u307E\u3059\u3002\u3053\u3053\u3067\u306F\u5149\u306E\u7D4C\u8DEF\u3092\u62E1\u5927\u3057\u3001\u3086\u3063\u304F\u308A\u8868\u793A\u3057\u3066\u3044\u307E\u3059\u3002","Wrist conditions":"\u624B\u9996\u306E\u72B6\u614B","Still \xB7 good contact":"\u9759\u6B62 \xB7 \u826F\u597D\u306A\u63A5\u89E6","Irregular movement":"\u4E0D\u898F\u5247\u306A\u52D5\u304D","Loose contact":"\u63A5\u89E6\u304C\u4E0D\u5B89\u5B9A","Low skin perfusion":"\u76AE\u819A\u306E\u8840\u6D41\u304C\u5C11\u306A\u3044","A regular optical pulse is easier to distinguish.":"\u898F\u5247\u7684\u306A\u8108\u6CE2\u306F\u3001\u307B\u304B\u306E\u5909\u52D5\u3068\u533A\u5225\u3057\u3084\u3059\u304F\u306A\u308A\u307E\u3059\u3002","Teaching-model estimate":"\u8AAC\u660E\u7528\u30E2\u30C7\u30EB\u306E\u63A8\u5B9A\u5024","Regular pulse":"\u898F\u5247\u7684\u306A\u8108\u6CE2","THE SIGNAL BENEATH THE NUMBER":"\u6570\u5024\u306E\u3082\u3068\u306B\u306A\u308B\u4FE1\u53F7","More blood. Less returned light.":"\u8840\u6DB2\u304C\u5897\u3048\u308B\u3068\u3001\u623B\u308B\u5149\u306F\u6E1B\u308B\u3002","The detector\u2019s dips repeat at the pulse rate. Inverting the clean optical change makes the rhythm easier to see.":"\u53D7\u5149\u91CF\u306E\u8C37\u304C\u8108\u62CD\u306B\u5408\u308F\u305B\u3066\u7E70\u308A\u8FD4\u3055\u308C\u307E\u3059\u3002\u30CE\u30A4\u30BA\u306E\u306A\u3044\u5149\u5B66\u5909\u5316\u3092\u53CD\u8EE2\u3059\u308B\u3068\u3001\u30EA\u30BA\u30E0\u304C\u898B\u3084\u3059\u304F\u306A\u308A\u307E\u3059\u3002","Inspect time":"\u89B3\u5BDF\u3059\u308B\u6642\u523B","Scrub to pause at any point in this four-second window.":"\u30B9\u30E9\u30A4\u30C0\u30FC\u3092\u52D5\u304B\u3059\u3068\u30014\u79D2\u9593\u306E\u4EFB\u610F\u306E\u6642\u70B9\u3067\u505C\u6B62\u3067\u304D\u307E\u3059\u3002","Returned light":"\u623B\u3063\u305F\u5149\u306E\u5F37\u3055","relative units":"\u76F8\u5BFE\u5358\u4F4D","\u2014 Detector signal":"\u2014 \u53D7\u5149\u4FE1\u53F7","Pulse component":"\u8108\u62CD\u6210\u5206",normalised:"\u6B63\u898F\u5316","Lower trace: clean teaching reference, not a claim that noise can always be removed. Vertical line: current inspection time.":"\u4E0B\u6BB5\u306F\u30CE\u30A4\u30BA\u306E\u306A\u3044\u53C2\u7167\u6CE2\u5F62\u3067\u3059\u3002\u5E38\u306B\u30CE\u30A4\u30BA\u3092\u9664\u53BB\u3067\u304D\u308B\u3053\u3068\u3092\u793A\u3059\u3082\u306E\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002\u7E26\u7DDA\u306F\u89B3\u5BDF\u4E2D\u306E\u6642\u523B\u3067\u3059\u3002","Optical pulse \u2260 ECG":"\u5149\u5B66\u5F0F\u306E\u8108\u6CE2\u3068\u5FC3\u96FB\u56F3\u306F\u5225\u306E\u3082\u306E","PPG tracks blood-volume changes at the wrist. The ECG feature on supported watches measures electrical activity using the back electrode and a finger on the Digital Crown. This optical experiment does not simulate ECG or blood oxygen.":"PPG\u306F\u624B\u9996\u306E\u8840\u6DB2\u91CF\u306E\u5909\u5316\u3092\u6349\u3048\u307E\u3059\u3002\u5BFE\u5FDC\u6A5F\u7A2E\u306E\u5FC3\u96FB\u56F3\u6A5F\u80FD\u306F\u3001\u80CC\u9762\u96FB\u6975\u3068Digital Crown\u306B\u89E6\u308C\u305F\u6307\u3092\u4F7F\u3063\u3066\u5FC3\u81D3\u306E\u96FB\u6C17\u6D3B\u52D5\u3092\u6E2C\u5B9A\u3057\u307E\u3059\u3002\u3053\u306E\u5149\u5B66\u5F0F\u306E\u5B9F\u9A13\u3067\u306F\u3001\u5FC3\u96FB\u56F3\u3084\u8840\u4E2D\u9178\u7D20\u306F\u518D\u73FE\u3057\u3066\u3044\u307E\u305B\u3093\u3002","What this model leaves out":"\u3053\u306E\u30E2\u30C7\u30EB\u306E\u7BC4\u56F2\u3068\u9650\u754C","Exterior proportions follow the 42 mm Series 10 (36 \xD7 42 \xD7 9.7 mm). The rear layout follows Apple\u2019s representative third-generation sensor diagram. Tissue, vessel size, ray paths, signal amplitudes and noise are illustrative; the cutaway gap is an inspection aid. The noise examples deliberately withhold an estimate; this is not a validated quality threshold. No live health data is collected, and Apple\u2019s proprietary estimator is not reproduced.":"\u5916\u5F62\u306E\u6BD4\u7387\u306F42 mm\u306ESeries 10\uFF0836 \xD7 42 \xD7 9.7 mm\uFF09\u3092\u53C2\u8003\u306B\u3057\u3066\u3044\u307E\u3059\u3002\u80CC\u9762\u306FApple\u306E\u7B2C3\u4E16\u4EE3\u30BB\u30F3\u30B5\u30FC\u306E\u4EE3\u8868\u56F3\u306B\u57FA\u3065\u304D\u307E\u3059\u3002\u7D44\u7E54\u3001\u8840\u7BA1\u306E\u5927\u304D\u3055\u3001\u5149\u306E\u7D4C\u8DEF\u3001\u4FE1\u53F7\u632F\u5E45\u3001\u30CE\u30A4\u30BA\u306F\u8AAC\u660E\u7528\u3067\u3001\u5C64\u306E\u9593\u9694\u306F\u89B3\u5BDF\u306E\u305F\u3081\u306B\u5E83\u3052\u3066\u3044\u307E\u3059\u3002\u30CE\u30A4\u30BA\u306E\u4F8B\u3067\u306F\u610F\u56F3\u7684\u306B\u63A8\u5B9A\u5024\u3092\u8868\u793A\u3057\u307E\u305B\u3093\u304C\u3001\u3053\u308C\u306F\u691C\u8A3C\u6E08\u307F\u306E\u54C1\u8CEA\u5224\u5B9A\u57FA\u6E96\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002\u5B9F\u969B\u306E\u5065\u5EB7\u30C7\u30FC\u30BF\u306F\u53CE\u96C6\u305B\u305A\u3001Apple\u72EC\u81EA\u306E\u63A8\u5B9A\u51E6\u7406\u3082\u518D\u73FE\u3057\u3066\u3044\u307E\u305B\u3093\u3002","Primary sources":"\u4E00\u6B21\u8CC7\u6599","Apple \xB7 Heart rate, calorimetry & activity (2024), pp. 4\u20138 \u2197":"Apple \xB7 \u5FC3\u62CD\u6570\u30FB\u6D88\u8CBB\u30AB\u30ED\u30EA\u30FC\u30FB\u6D3B\u52D5\u91CF\uFF082024\u5E74\uFF09\u30014\u301C8\u30DA\u30FC\u30B8 \u2197","Apple \xB7 How heart rate is measured \u2197":"Apple \xB7 \u5FC3\u62CD\u6570\u306E\u6E2C\u5B9A\u65B9\u6CD5 \u2197","Apple \xB7 Fit, motion & skin perfusion \u2197":"Apple \xB7 \u88C5\u7740\u72B6\u614B\u30FB\u52D5\u304D\u30FB\u76AE\u819A\u306E\u8840\u6D41 \u2197","Apple \xB7 Series 10 technical specifications \u2197":"Apple \xB7 Series 10\u306E\u6280\u8853\u4ED5\u69D8 \u2197","Independent educational model \xB7 Not affiliated with Apple":"\u72EC\u7ACB\u3057\u305F\u5B66\u7FD2\u7528\u30E2\u30C7\u30EB \xB7 Apple\u306E\u516C\u5F0F\u30B3\u30F3\u30C6\u30F3\u30C4\u3067\u306F\u3042\u308A\u307E\u305B\u3093","Blood changes the light that returns.":"\u8840\u6DB2\u91CF\u306B\u3088\u3063\u3066\u3001\u623B\u308B\u5149\u304C\u5909\u308F\u308A\u307E\u3059\u3002","Each arterial pulse briefly increases blood volume in the wrist. More green light is absorbed, so less returns to the detector.":"\u52D5\u8108\u306E\u62CD\u52D5\u3054\u3068\u306B\u3001\u624B\u9996\u306E\u8840\u6DB2\u91CF\u304C\u4E00\u6642\u7684\u306B\u5897\u3048\u307E\u3059\u3002\u7DD1\u8272\u5149\u304C\u3088\u308A\u591A\u304F\u5438\u53CE\u3055\u308C\u3001\u53D7\u5149\u90E8\u306B\u623B\u308B\u5149\u306F\u5C11\u306A\u304F\u306A\u308A\u307E\u3059\u3002","More blood \u2192 more absorption \u2192 less return":"\u8840\u6DB2\u91CF\u304C\u5897\u3048\u308B \u2192 \u5438\u53CE\u304C\u5897\u3048\u308B \u2192 \u623B\u308B\u5149\u304C\u6E1B\u308B","Timing becomes beats per minute.":"\u7E70\u308A\u8FD4\u3057\u306E\u9593\u9694\u3092\u3001\u5FC3\u62CD\u6570\u306B\u5909\u3048\u307E\u3059\u3002","The repeating optical change is photoplethysmography (PPG). This teaching estimator finds pulse intervals in a clean signal; Apple\u2019s own processing is more sophisticated.":"\u5149\u306E\u5909\u5316\u304B\u3089\u8108\u6CE2\u3092\u6E2C\u308B\u65B9\u6CD5\u3092\u5149\u96FB\u5F0F\u5BB9\u7A4D\u8108\u6CE2\u8A18\u9332\u6CD5\uFF08PPG\uFF09\u3068\u3044\u3044\u307E\u3059\u3002\u3053\u306E\u8AAC\u660E\u7528\u30E2\u30C7\u30EB\u306F\u660E\u77AD\u306A\u4FE1\u53F7\u304B\u3089\u62CD\u52D5\u306E\u9593\u9694\u3092\u6C42\u3081\u307E\u3059\u3002Apple\u306E\u5B9F\u969B\u306E\u51E6\u7406\u306F\u3001\u3055\u3089\u306B\u8907\u96D1\u3067\u3059\u3002","Heart rate = 60 \xF7 interval in seconds":"\u5FC3\u62CD\u6570 = 60 \xF7 \u62CD\u52D5\u306E\u9593\u9694\uFF08\u79D2\uFF09","A pulse can be hidden by noise.":"\u30CE\u30A4\u30BA\u306B\u8108\u62CD\u304C\u96A0\u308C\u308B\u3053\u3068\u304C\u3042\u308A\u307E\u3059\u3002","Movement and changing contact also alter returned light. Try irregular movement or low perfusion: the pulse still exists, but it may no longer be reliable to measure.":"\u52D5\u304D\u3084\u63A5\u89E6\u72B6\u614B\u306E\u5909\u5316\u3082\u3001\u623B\u308B\u5149\u3092\u5909\u52D5\u3055\u305B\u307E\u3059\u3002\u4E0D\u898F\u5247\u306A\u52D5\u304D\u3084\u8840\u6D41\u306E\u5C11\u306A\u3044\u72B6\u614B\u3092\u8A66\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u8108\u62CD\u304C\u3042\u3063\u3066\u3082\u3001\u78BA\u5B9F\u306B\u6E2C\u308C\u308B\u3068\u306F\u9650\u308A\u307E\u305B\u3093\u3002","A visible fluctuation is not always a heartbeat":"\u898B\u3048\u3066\u3044\u308B\u5909\u52D5\u304C\u3001\u3059\u3079\u3066\u62CD\u52D5\u3068\u306F\u9650\u308A\u307E\u305B\u3093","Movement adds changes unrelated to the heartbeat. Apple uses motion information and signal processing; rejection here is illustrative.":"\u52D5\u304D\u306F\u5FC3\u62CD\u4EE5\u5916\u306E\u5909\u52D5\u3092\u52A0\u3048\u307E\u3059\u3002Apple\u306F\u52D5\u304D\u306E\u60C5\u5831\u3068\u4FE1\u53F7\u51E6\u7406\u3092\u5229\u7528\u3057\u307E\u3059\u3002\u3053\u3053\u3067\u306E\u6E2C\u5B9A\u4E0D\u53EF\u306E\u5224\u5B9A\u306F\u8AAC\u660E\u7528\u3067\u3059\u3002","Motion obscures pulse":"\u52D5\u304D\u304C\u8108\u6CE2\u3092\u59A8\u3052\u308B","Changing sensor contact adds large fluctuations and weakens the pulse signal.":"\u30BB\u30F3\u30B5\u30FC\u306E\u63A5\u89E6\u72B6\u614B\u304C\u5909\u308F\u308B\u3068\u3001\u5927\u304D\u306A\u5909\u52D5\u304C\u52A0\u308F\u308A\u3001\u8108\u62CD\u306E\u4FE1\u53F7\u304C\u5F31\u307E\u308A\u307E\u3059\u3002","Contact is unstable":"\u63A5\u89E6\u304C\u4E0D\u5B89\u5B9A","Lower blood flow through skin can make the pulsatile optical component smaller.":"\u76AE\u819A\u3092\u6D41\u308C\u308B\u8840\u6DB2\u304C\u5C11\u306A\u3044\u3068\u3001\u5149\u306E\u62CD\u52D5\u6210\u5206\u304C\u5C0F\u3055\u304F\u306A\u308B\u3053\u3068\u304C\u3042\u308A\u307E\u3059\u3002","Pulse is weak":"\u8108\u6CE2\u304C\u5F31\u3044","Infrared LEDs also send light into the wrist. Apple uses infrared for background heart rate checks; the violet paths here make otherwise invisible light visible.":"\u8D64\u5916LED\u3082\u624B\u9996\u306B\u5149\u3092\u9001\u308A\u307E\u3059\u3002Apple\u306F\u30D0\u30C3\u30AF\u30B0\u30E9\u30A6\u30F3\u30C9\u6E2C\u5B9A\u306B\u8D64\u5916\u5149\u3092\u4F7F\u3044\u307E\u3059\u3002\u3053\u3053\u3067\u306F\u76EE\u306B\u898B\u3048\u306A\u3044\u5149\u3092\u7D2B\u8272\u3067\u793A\u3057\u3066\u3044\u307E\u3059\u3002","Infrared is invisible to your eyes; violet is a teaching colour. Background readings are intermittent, not continuous.":"\u8D64\u5916\u5149\u306F\u76EE\u306B\u898B\u3048\u307E\u305B\u3093\u3002\u7D2B\u8272\u306F\u8AAC\u660E\u306E\u305F\u3081\u306E\u8868\u793A\u3067\u3059\u3002\u30D0\u30C3\u30AF\u30B0\u30E9\u30A6\u30F3\u30C9\u6E2C\u5B9A\u306F\u9023\u7D9A\u3067\u306F\u306A\u304F\u3001\u9593\u6B20\u7684\u306B\u884C\u308F\u308C\u307E\u3059\u3002","Noise changes the detector trace, even though the underlying pulse keeps its rhythm. The lower trace shows that known pulse as a teaching reference.":"\u8108\u62CD\u306E\u30EA\u30BA\u30E0\u304C\u540C\u3058\u3067\u3082\u3001\u30CE\u30A4\u30BA\u306B\u3088\u3063\u3066\u53D7\u5149\u4FE1\u53F7\u306F\u5909\u308F\u308A\u307E\u3059\u3002\u4E0B\u6BB5\u306B\u306F\u3001\u30E2\u30C7\u30EB\u3067\u8A2D\u5B9A\u3057\u305F\u8108\u6CE2\u3092\u53C2\u7167\u7528\u306B\u793A\u3057\u3066\u3044\u307E\u3059\u3002",unreliable:"\u6E2C\u5B9A\u56F0\u96E3","OPTICAL SENSOR \xB7 REAR":"\u5149\u5B66\u30BB\u30F3\u30B5\u30FC \xB7 \u80CC\u9762","SERIES 10 \xB7 EXTERIOR":"SERIES 10 \xB7 \u5916\u89B3","Representative sensor layout":"\u4EE3\u8868\u7684\u306A\u30BB\u30F3\u30B5\u30FC\u914D\u7F6E","42 mm case \xB7 reconstructed exterior":"42 mm\u30B1\u30FC\u30B9 \xB7 \u5916\u89B3\u306E\u518D\u69CB\u6210","LED emitters":"LED\u767A\u5149\u90E8","Returning light":"\u623B\u308B\u5149","Arterial pulse":"\u52D5\u8108\u306E\u62CD\u52D5","Skin layers":"\u76AE\u819A\u306E\u5C64",Photodiodes:"\u30D5\u30A9\u30C8\u30C0\u30A4\u30AA\u30FC\u30C9",LEDs:"LED","Back electrode":"\u80CC\u9762\u96FB\u6975","HEART RATE":"\u5FC3\u62CD\u6570","TEACHING MODEL":"\u8AAC\u660E\u7528\u30E2\u30C7\u30EB","Orbitable 3D Apple Watch and illustrative wrist tissue":"\u56DE\u8EE2\u3057\u3066\u89B3\u5BDF\u3067\u304D\u308BApple Watch\u3068\u624B\u9996\u306E\u7D44\u7E54\u30E2\u30C7\u30EB","Synchronized pulse signals":"\u9023\u52D5\u3059\u308B\u8108\u6CE2\u4FE1\u53F7","Returned light signal over four seconds. Increased arterial blood volume produces a dip.":"4\u79D2\u9593\u306E\u53D7\u5149\u4FE1\u53F7\u3002\u52D5\u8108\u8840\u6DB2\u91CF\u304C\u5897\u3048\u308B\u3068\u3001\u5149\u306E\u5F37\u3055\u304C\u4F4E\u4E0B\u3057\u307E\u3059\u3002","Ideal inverted optical pulse, showing beat intervals. This is the clean teaching reference, not recovered Apple Watch data.":"\u62CD\u52D5\u306E\u9593\u9694\u3092\u793A\u3059\u53CD\u8EE2\u3057\u305F\u7406\u60F3\u8108\u6CE2\u3002\u30CE\u30A4\u30BA\u306E\u306A\u3044\u8AAC\u660E\u7528\u6CE2\u5F62\u3067\u3042\u308A\u3001Apple Watch\u306E\u5B9F\u6E2C\u30C7\u30FC\u30BF\u304B\u3089\u5FA9\u5143\u3057\u305F\u3082\u306E\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002","Beat interval 0.833 s \xB7 60 \xF7 0.833 \u2248 72 bpm":"\u62CD\u52D5\u306E\u9593\u9694 0.833 \u79D2 \xB7 60 \xF7 0.833 \u2248 72 bpm"};var br=document.documentElement.lang==="ja",Er=i=>br?Ri[i]??i:i;function Lo(){if(!br)return;let i=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);for(;i.nextNode();){let t=i.currentNode;if(["SCRIPT","STYLE"].includes(t.parentElement?.tagName))continue;let e=t.textContent.trim();Ri[e]&&(t.textContent=t.textContent.replace(e,Ri[e]))}for(let t of document.querySelectorAll("[aria-label]")){let e=t.getAttribute("aria-label");Ri[e]&&t.setAttribute("aria-label",Ri[e])}}var Kn={LEFT:0,MIDDLE:1,RIGHT:2,ROTATE:0,DOLLY:1,PAN:2},jn={ROTATE:0,PAN:1,DOLLY_PAN:2,DOLLY_ROTATE:3},kc=0,_l=1,Vc=2;var xl=1,Hc=2,xn=3,In=0,Ee=1,yn=2,Un=0,hi=1,yl=2,vl=3,Ml=4,Gc=5,qn=100,Wc=101,Xc=102,qc=103,Yc=104,Zc=200,Jc=201,$c=202,Kc=203,Zr=204,Jr=205,jc=206,Qc=207,th=208,eh=209,nh=210,ih=211,sh=212,rh=213,ah=214,ba=0,Ea=1,Ta=2,ui=3,wa=4,Aa=5,Ra=6,Ca=7,Pa=0,oh=1,lh=2,Nn=0,ch=1,hh=2,uh=3,Ia=4,dh=5,fh=6,ph=7;var Sl=300,_i=301,xi=302,Da=303,La=304,dr=306,$r=1e3,Xn=1001,Kr=1002,Ne=1003,mh=1004;var fr=1005;var o